from typing import List

class Solution:
    def criticalConnections(self, V: int, adj: List[List[int]]) -> List[List[int]]:
        disc = [-1] * V
        low = [-1] * V
        parent = [-1] * V
        timer = [0]
        bridges = []

        def dfs(u: int):
            disc[u] = low[u] = timer[0]
            timer[0] += 1

            for v in adj[u]:
                if disc[v] == -1:
                    parent[v] = u
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        edge = sorted([u, v])
                        bridges.append(edge)
                elif v != parent[u]:
                    low[u] = min(low[u], disc[v])

        for i in range(V):
            if disc[i] == -1:
                dfs(i)

        bridges.sort()
        return bridges
